<template><div class="page"><div class="toolbar"><h2>登录日志</h2><el-button @click="load">刷新</el-button></div><PageTable title="登录日志" :rows="rows" :columns="columns" :total="total" :page="page" :loading="loading" @page-change="changePage"/></div></template><script setup lang="ts">import{onMounted,ref}from'vue';import PageTable from'@/components/common/PageTable.vue';import{loginLogs}from'@/api/log';const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false);const columns=[{prop:'username',label:'用户'},{prop:'ip',label:'IP'},{prop:'status',label:'状态'},{prop:'message',label:'消息'},{prop:'createdAt',label:'时间'}];const load=async()=>{loading.value=true;try{const r:any=await loginLogs({page:page.value,size:10});rows.value=r.data.records;total.value=r.data.total}finally{loading.value=false}};const changePage=(v:number)=>{page.value=v;load()};onMounted(load)</script>
